// The benign baseline: a local build step. No network, no credentials, no
// indirection — this is what the package looked like when it was approved.
const fs = require("fs");
const path = require("path");

const out = path.join(__dirname, "dist");
fs.mkdirSync(out, { recursive: true });
fs.writeFileSync(path.join(out, "index.js"), "module.exports = {};\n");
